/bin/bash -lc "Rscript - <<'RS'
files <- c('inputs/res_1vs97.rds','inputs/res_1vs98.rds','inputs/res_1vs99.rds')
for (f in files) {
  cat('FILE', f, '\\n')
  x <- readRDS(f)
  cat('class:', paste(class(x), collapse=','), '\\n')
  cat('isS4:', isS4(x), '\\n')
  cat('slots:', paste(slotNames(x), collapse=','), '\\n')
  if ('elementMetadata' %in% slotNames(x)) {
    em <- slot(x, 'elementMetadata')
    cat('elementMetadata class:', paste(class(em), collapse=','), '\\n')
    cat('em slots:', paste(slotNames(em), collapse=','), '\\n')
  }
  if ('listData' %in% slotNames(x)) {
    ld <- slot(x, 'listData')
    cat('listData names:', paste(names(ld), collapse=','), '\\n')
    cat('listData classes:', paste(vapply(ld, function(z) paste(class(z), collapse='/'), character(1)), collapse=','), '\\n')
    cat('lengths:', paste(vapply(ld, length, integer(1)), collapse=','), '\\n')
    for (nm in names(ld)) {
      z <- ld[[nm]]
      cat(nm, 'head:', paste(utils::head(z, 5), collapse=','), '\\n')
    }
  }
  if ('rownames' %in% slotNames(x)) cat('rownames head:', paste(utils::head(slot(x,'rownames'), 10), collapse=','), '\\n')
  cat('\\n')
}
RS"

